import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { SemiFinishedService } from '../../services/semi-finished-service';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';

import { SemiFinished } from '../../models/invoice';

export type { SemiFinished };

@Component({
  selector: 'app-semi-finished',
  imports: [ CommonModule, FormsModule, RouterLink],
  templateUrl: './semi-finished.html',
  styleUrl: './semi-finished.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SemiFinishedComponent {
semiFinished: SemiFinished[] = [];
  searchTerm = '';

  constructor(private service: SemiFinishedService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.service.getAllProducts().subscribe({
      next: (data) => {
        this.semiFinished = data;
         this.cd.markForCheck();
        console.log("Products from backend:", this.semiFinished);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  filteredProducts() {
    const term = this.searchTerm.toLowerCase();
    return this.semiFinished.filter(s =>
      s.name.toLowerCase().includes(term) ||
      s.price.toPrecision().includes(term) 
    );
  }
}
